func:
// Two real freezers. Internal thermostats are set to minimum so the
// outlet is the effective thermostat. The planner only needs the hard
// ceiling (t_max_c) and the thermal model; there is no low/high target.
// safety_margin_c is subtracted from t_max_c when planning so 15-min
// slot granularity can't overshoot in practice.
//
// Failsafe outlet control. We only ever publish an OFF command: Tasmota's
// 'tm/cmnd/<dev>/event' poweroff and HomeMatic's PRESS_SHORT on the
// KuehltruheAus program each trigger a device-side rule that switches the
// outlet off for a bounded time and then auto-restores. Re-publishing each
// heartbeat extends the off-timer; if Node-RED stops, the outlet turns
// itself back on so the freezer can't be stranded off. min_on_minutes
// gates ON->OFF so a cooling cycle runs for at least 2 price slots once
// it has started.
// pwr_parse_kind drives fc_pwr_parse: 'tasmota' uses ENERGY.Power,
// 'homematic' uses payload directly (number or {val}).
const cfg = {
  pv_base_load_w: 400,
  min_on_minutes: 30,
  safety_margin_c: 0.5,
  freezers: {
    og_gefrierschrank: {
      temp_topic: 'sensor/status/temperature/og_speis/ht/4',
      pwr_topic: 'tm/tele/OgSpGfr/SENSOR',
      pwr_parse_kind: 'tasmota',
      off_cmd_topic: 'tm/cmnd/OgSpGfr/event',
      off_cmd_payload: 'poweroff',
      // Thermal-model training series:
      //   temperature: infra.temperature WHERE "Device" = temp_device
      //   power:       tmp.power         WHERE  device  = power_device
      temp_device: 'ht4',
      power_device: 'OgSpGfr',
      t_max_c: -16,
      fallback_cooling_rate_c_per_min: -0.25,
      fallback_warming_rate_c_per_min: 0.030,
      fallback_running_power_w: 120
    },
    kg_kuehltruhe: {
      temp_topic: 'sensor/status/temperature/kg_garage/ht/1',
      pwr_topic: 'hm/status/HM-ES-PMSw1-Pl NEQ1809653:2/POWER',
      pwr_parse_kind: 'homematic',
      off_cmd_topic: 'hm/set/KuehltruheAus/PRESS_SHORT',
      off_cmd_payload: 1,
      temp_device: 'ht1',
      power_device: 'NEQ1809653',
      t_max_c: -16,
      fallback_cooling_rate_c_per_min: -0.20,
      fallback_warming_rate_c_per_min: 0.025,
      fallback_running_power_w: 100
    }
  }
};
flow.set('config', cfg);

const freezers = global.get('freezers') || {};
for (const name of Object.keys(cfg.freezers)) {
  if (!freezers[name]) {
    freezers[name] = {
      name: name,
      state: 'idle',
      reason: 'init',
      override: 'AUTO',
      current_temp_c: null,
      current_power_w: null,
      last_temp_update: null,
      last_power_update: null,
      last_state_change_at: Date.now(),
      last_decision_at: null,
      last_status_published_at: null,
      last_status_key: null,
      model: {
        cooling_rate_c_per_min: cfg.freezers[name].fallback_cooling_rate_c_per_min,
        warming_rate_c_per_min: cfg.freezers[name].fallback_warming_rate_c_per_min,
        running_power_w: cfg.freezers[name].fallback_running_power_w,
        samples: 0,
        last_refresh: null
      }
    };
  }
}
// Prune stale placeholder devices no longer in cfg.
for (const k of Object.keys(freezers)) {
  if (!cfg.freezers[k]) delete freezers[k];
}
global.set('freezers', freezers);
return null;

// Sensor payload for both freezers is {value: <degC>, id, name, tst}.
const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
let device = null;
for (const name of Object.keys(fs)) {
  if (fs[name].temp_topic === msg.topic) { device = name; break; }
}
if (!device) return null;
const p = msg.payload;
if (!p || typeof p !== 'object' || p.value == null) return null;
const t = Number(p.value);
if (isNaN(t)) return null;
return { topic: 'home/freezer/' + device + '/temperature', payload: t, device_name: device };

// Looks up the device by MQTT topic and extracts power in W.
// Tasmota publishes {ENERGY:{Power: N, ...}}; Homematic publishes a raw
// number or {val:N}. Dispatch on fcfg.pwr_parse_kind.
const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
let device = null, fcfg = null;
for (const name of Object.keys(fs)) {
  if (fs[name].pwr_topic === msg.topic) { device = name; fcfg = fs[name]; break; }
}
if (!device) return null;
const p = msg.payload;
let w = null;
if (fcfg.pwr_parse_kind === 'tasmota') {
  if (!p || !p.ENERGY || p.ENERGY.Power == null) return null;
  w = Number(p.ENERGY.Power);
} else if (fcfg.pwr_parse_kind === 'homematic') {
  if (typeof p === 'number') w = p;
  else if (typeof p === 'string') w = Number(p);
  else if (p && p.val != null) w = Number(p.val);
} else {
  return null;
}
if (w == null || isNaN(w)) return null;
return { topic: 'home/freezer/' + device + '/power', payload: w, device_name: device };

// Merges the latest temperature or power reading into global.freezers[<name>].
// Temperature updates re-evaluate the decision synchronously so the outlet
// reacts to the reading that pushed it over the ceiling. Power updates only
// refresh state — they don't affect the decision and firing decide on each
// would flood the status topic (HM publishes power every few seconds).
const name = msg.device_name;
if (!name) return null;
const topic = msg.topic || '';
const freezers = global.get('freezers') || {};
const dev = freezers[name];
if (!dev) return null;
const now = Date.now();
let trigger = null;
if (topic.endsWith('/temperature')) {
  dev.current_temp_c = Number(msg.payload);
  dev.last_temp_update = now;
  trigger = 'temp';
} else if (topic.endsWith('/power')) {
  dev.current_power_w = Number(msg.payload);
  dev.last_power_update = now;
}
freezers[name] = dev;
global.set('freezers', freezers);
if (trigger !== 'temp') return null;
return { device_name: name, payload: dev, trigger: 'state_update' };

const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
const out = [];
for (const name of Object.keys(fs)) {
  out.push({ device_name: name, trigger: 'tick' });
}
return [out];

function localIso(ms){const d=new Date(ms);const pad=n=>String(n).padStart(2,'0');const off=-d.getTimezoneOffset();const sign=off>=0?'+':'-';const oh=pad(Math.floor(Math.abs(off)/60));const om=pad(Math.abs(off)%60);return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds())+sign+oh+':'+om;}
const SLOT_MS = 15 * 60000;
const SLOT_MIN = 15;
const STATUS_HEARTBEAT_MS = 2 * 60000;

const isTest = !!msg._test;
const t = isTest ? msg._test : null;
const name = isTest ? t.device_name : msg.device_name;
if (!name) return null;
const trigger = isTest ? null : (msg.trigger || null);

const cfg = isTest ? t.cfg : (flow.get('config') || {});
const fcfg = (cfg.freezers || {})[name];
if (!fcfg) return null;

const freezers = isTest ? (t.freezers || {}) : (global.get('freezers') || {});
const dev = freezers[name];
if (!dev) return null;

const now = isTest && t.now != null ? t.now : Date.now();

// Price slots. global.pp.price24 is a dict keyed by HHMM with entries
// {idx, val (ct/kWh), from}. The planner needs the same schema so it can
// attach a per-freezer plan back onto every slot.
const p24 = isTest ? (t.price24 || {}) : (((global.get('pp', 'file') || {}).price24) || {});
const slotsAll = [];
for (const k of Object.keys(p24)) {
  const s = p24[k];
  if (!s || typeof s !== 'object' || !s.from) continue;
  const st = new Date(s.from).getTime();
  const v = Number(s.val);
  if (isNaN(st) || isNaN(v)) continue;
  slotsAll.push({ key: k, t: st, price_ct: v, price_eur_kwh: v / 100, from: s.from });
}
slotsAll.sort((a, b) => a.t - b.t);
// The active horizon starts with the slot that covers 'now'.
const active = slotsAll.filter(s => s.t + SLOT_MS > now);

const pv_now = Math.max(0, Number(isTest ? t.ess_pac : ((global.get('ess') || {}).pac)) || 0);
const pv_base_load_w = cfg.pv_base_load_w || 0;

const T = dev.current_temp_c;
const T_max = fcfg.t_max_c;
const safetyMarginC = cfg.safety_margin_c != null ? cfg.safety_margin_c : 0.5;
const T_plan_max = T_max - safetyMarginC;
const wasOn = (dev.state === 'cooling' || dev.state === 'safety');
const model = dev.model || {};
const cooling = Number(model.cooling_rate_c_per_min) || fcfg.fallback_cooling_rate_c_per_min || -0.25;
const warming = Math.max(0.005, Number(model.warming_rate_c_per_min) || fcfg.fallback_warming_rate_c_per_min || 0.03);
const load = Number(model.running_power_w) || fcfg.fallback_running_power_w || 120;

// Per-slot PV / load forecast from global.pp.prediction (same source the
// battery controller publishes). Each prediction entry has a local-time
// label 'DD.MM., HH:MM'; parse against now()'s year to get a ms key and
// look up by slot.t. When no prediction entry matches, fall back to live
// PV for the current slot only and pv_base_load_w for baseline load.
const predArr = isTest ? (t.prediction || []) : (((global.get('pp', 'file') || {}).prediction) || []);
const predByT = new Map();
function parsePredTime(s) {
  const m = /^(\d{2})\.(\d{2})\.,\s*(\d{2}):(\d{2})$/.exec(s || '');
  if (!m) return NaN;
  const year = new Date(now).getFullYear();
  return new Date(year, parseInt(m[2]) - 1, parseInt(m[1]), parseInt(m[3]), parseInt(m[4]), 0, 0).getTime();
}
for (const e of predArr) {
  const ts = parsePredTime(e && e.time);
  if (!isNaN(ts)) predByT.set(ts, e);
}
// PV-over-price priority: tier 0 = slot has any PV surplus after the
// house base load, tier 1 = runs purely on grid. The greedy picks the
// lowest-tier candidate first so a solar-covered slot always beats a
// cheaper grid slot; cost only breaks ties inside a tier.
function slotMetrics(slot, i) {
  const pe = predByT.get(slot.t);
  const pvW = pe && pe.pvPower != null ? Number(pe.pvPower) : (i === 0 ? pv_now : 0);
  const baseLoadW = pe && pe.loadEst != null ? Number(pe.loadEst) : pv_base_load_w;
  const pv_surplus = Math.max(0, pvW - baseLoadW);
  const netGridW = Math.max(0, load - pv_surplus);
  const tier = pv_surplus > 0 ? 0 : 1;
  const cost = (netGridW * (SLOT_MIN / 60) / 1000) * slot.price_eur_kwh;
  return { tier: tier, cost: cost, pv_w: pvW, pv_surplus: pv_surplus };
}

function simulate(on, startT) {
  let Tx = startT;
  const temps = [];
  for (let i = 0; i < on.length; i++) {
    const rate = on[i] ? cooling : warming;
    Tx += rate * SLOT_MIN;
    temps.push(Tx);
  }
  return temps;
}

// Greedy: start all-OFF, find the first slot where the simulated temp
// exceeds T_plan_max, add the cheapest still-OFF slot in [0..violation],
// repeat. Optimal for a linear thermal model because every forced-ON slot
// lowers all subsequent temps by the same (cooling - warming) * 15 min,
// so picking the cheapest forced slot minimises total cost under the
// max-temperature constraint.
function planOutlet(startT) {
  const N = active.length;
  const on = new Array(N).fill(false);
  if (N === 0) return { on: [], temps: [], feasible: true };
  if (startT >= T_plan_max) on[0] = true;
  const MAX_ITER = N + 2;
  let feasible = true;
  for (let iter = 0; iter < MAX_ITER; iter++) {
    const temps = simulate(on, startT);
    let violation = -1;
    for (let i = 0; i < N; i++) {
      if (temps[i] > T_plan_max) { violation = i; break; }
    }
    if (violation < 0) break;
    let bestI = -1, bestM = null;
    for (let j = 0; j <= violation; j++) {
      if (on[j]) continue;
      const m = slotMetrics(active[j], j);
      if (!bestM || m.tier < bestM.tier || (m.tier === bestM.tier && m.cost < bestM.cost)) {
        bestM = m; bestI = j;
      }
    }
    if (bestI < 0) { feasible = false; break; }
    on[bestI] = true;
  }
  return { on, temps: simulate(on, startT), feasible };
}

// Respect explicit user override first.
if (dev.override === 'ON')  return buildResult(true,  'override_on',  null);
if (dev.override === 'OFF') return buildResult(false, 'override_off', null);

// No temperature yet - cautious: keep current state, no switch change.
if (T == null || isNaN(T)) return buildResult(wasOn, 'no_reading', null);

// Hard safety ceiling trumps planning.
if (T >= T_max) return buildResult(true, 'safety_ceiling', null);

const planResult = planOutlet(T);
const wantOnNow = active.length > 0 ? planResult.on[0] : false;
const reason = !planResult.feasible ? 'plan_infeasible' : (wantOnNow ? 'plan_cool' : 'plan_off');
return buildResult(wantOnNow, reason, planResult);

function buildResult(wantOn, reason, planResult) {
  const command = wantOn ? 'ON' : 'OFF';
  const newState = wantOn ? (T != null && T >= T_max ? 'safety' : 'cooling') : 'idle';
  const changed = newState !== dev.state;
  const minOnMs = (cfg.min_on_minutes || 0) * 60000;
  const sinceChange = now - (dev.last_state_change_at || 0);
  // Only gate ON->OFF: guarantee a cooling cycle runs for at least
  // min_on_minutes once it starts. OFF->ON is never gated (the outlet
  // failsafe turns the freezer back on anyway if we stop extending the
  // off-timer). Safety ceiling and explicit overrides bypass the gate.
  const gated = wasOn && !wantOn && reason !== 'safety_ceiling' && reason !== 'override_on' && reason !== 'override_off' && sinceChange < minOnMs;

  if (isTest) {
    const expected = t.expected || null;
    let pass = null;
    if (expected) {
      pass = true;
      if (expected.command && expected.command !== command) pass = false;
      if (expected.reason && expected.reason !== reason) pass = false;
      if (expected.state && expected.state !== newState) pass = false;
    }
    return [null, null, {
      topic: 'test/' + (t.label || name),
      payload: {
        label: t.label || null,
        pass: pass,
        expected: expected,
        got: { command: command, reason: reason, state: newState, gated: gated },
        diagnostics: {
          now: localIso(now),
          temp_c: T,
          t_max: T_max,
          t_plan_max: T_plan_max,
          pv_now_w: Math.round(pv_now),
          cooling_rate: cooling,
          warming_rate: warming,
          running_power_w: load,
          slots: active.length,
          feasible: planResult ? planResult.feasible : null,
          first_on: planResult && planResult.on.length > 0 ? planResult.on[0] : null,
          first_temp: planResult && planResult.temps.length > 0 ? Math.round(planResult.temps[0] * 10) / 10 : null,
          on_slots: planResult ? planResult.on.filter(v => v).length : null
        }
      }
    }];
  }

  // Persist the combined per-freezer plan. Clone price24 structure, keep
  // other freezers' entries intact, overwrite this device's slice.
  if (planResult) {
    const prev = global.get('freezer_plan') || {};
    const newPlan = {};
    for (const k of Object.keys(p24)) {
      const src = p24[k];
      const prevEntry = prev[k];
      const freezersEntries = (prevEntry && prevEntry.freezers) ? Object.assign({}, prevEntry.freezers) : {};
      delete freezersEntries[name];
      newPlan[k] = Object.assign({}, src, { freezers: freezersEntries });
    }
    for (let i = 0; i < active.length; i++) {
      const k = active[i].key;
      if (newPlan[k]) {
        newPlan[k].freezers[name] = {
          state: planResult.on[i] ? 'ON' : 'OFF',
          temp: Math.round(planResult.temps[i] * 10) / 10
        };
      }
    }
    global.set('freezer_plan', newPlan);
  }

  // Hysteresis on MQTT: only publish status when state, reason or command
  // changes, or once every STATUS_HEARTBEAT_MS on the eval tick.
  const effectiveReason = gated ? 'gated_min_on' : reason;
  const effectiveState = gated ? dev.state : newState;
  const statusKey = effectiveState + '|' + effectiveReason + '|' + command;
  const lastPub = dev.last_status_published_at || 0;
  const heartbeatDue = trigger === 'tick' && (now - lastPub) >= STATUS_HEARTBEAT_MS;
  const statusChanged = dev.last_status_key !== statusKey;
  const shouldPublishStatus = statusChanged || heartbeatDue;

  if (gated) {
    dev.last_decision_at = now;
    // Safety heartbeat: resend the current outlet command so the outlet
    // stays in sync even while gated (no state change yet).
    const actualCmd = (dev.state === 'cooling' || dev.state === 'safety') ? 'ON' : 'OFF';
    const switchMsg = heartbeatDue ? { topic: 'home/freezer/' + name + '/set', payload: actualCmd } : null;
    let statusMsg = null;
    if (shouldPublishStatus) {
      statusMsg = {
        topic: 'home/freezer/' + name + '/status',
        payload: JSON.stringify({
          state: dev.state, reason: 'gated_min_on', device: name,
          temp_c: T, target_command: command, intended_reason: reason,
          temp_max_c: T_max,
          pv_now_w: Math.round(pv_now),
          updated_at: localIso(now)
        }),
        retain: true
      };
      dev.last_status_published_at = now;
      dev.last_status_key = statusKey;
    }
    freezers[name] = dev;
    global.set('freezers', freezers);
    return [switchMsg, statusMsg, null];
  }
  if (changed) {
    dev.state = newState;
    dev.last_state_change_at = now;
  }
  dev.reason = reason;
  dev.last_decision_at = now;
  // Safety: resend the outlet command on every heartbeat tick so a lost
  // MQTT message or rebooted outlet still converges to the intended state.
  const switchMsg = (changed || heartbeatDue) ? { topic: 'home/freezer/' + name + '/set', payload: command } : null;
  let statusMsg = null;
  if (shouldPublishStatus) {
    const plan = planResult ? planResult.on.map((s, i) => {
      const pe = predByT.get(active[i].t);
      return {
        time: active[i].from,
        state: s ? 'ON' : 'OFF',
        temp: Math.round(planResult.temps[i] * 10) / 10,
        pv_w: pe && pe.pvPower != null ? Math.round(Number(pe.pvPower)) : null
      };
    }) : [];
    statusMsg = {
      topic: 'home/freezer/' + name + '/status',
      payload: JSON.stringify({
        state: newState, reason: reason, device: name,
        temp_c: T, temp_max_c: T_max,
        current_power_w: dev.current_power_w,
        pv_now_w: Math.round(pv_now),
        plan_slots: plan.length,
        plan_on_slots: planResult ? planResult.on.filter(v => v).length : 0,
        plan: plan,
        plan_feasible: planResult ? planResult.feasible : null,
        updated_at: localIso(now),
        model: dev.model
      }),
      retain: true
    };
    dev.last_status_published_at = now;
    dev.last_status_key = statusKey;
  }
  freezers[name] = dev;
  global.set('freezers', freezers);
  return [switchMsg, statusMsg, null];
}

// Failsafe switch mapping. We publish only the OFF command; the outlet-
// side rule (Tasmota event:poweroff / HomeMatic KuehltruheAus PRESS_SHORT)
// switches off for a bounded time and auto-restores. Re-publishing each
// heartbeat extends the off-timer. An ON 'intent' is a no-op - stopping
// OFF messages is what lets the outlet come back on, which is the
// failsafe: if Node-RED dies, both freezers power up on their own.
const parts = (msg.topic || '').split('/');
if (parts.length < 4 || parts[0] !== 'home' || parts[1] !== 'freezer') return null;
const name = parts[2];
const action = String(msg.payload).toUpperCase();
if (action !== 'OFF') return null;
const cfg = flow.get('config') || {};
const fcfg = (cfg.freezers || {})[name];
if (!fcfg) { node.warn('switch router: unknown freezer ' + name); return null; }
if (!fcfg.off_cmd_topic) { node.warn('switch router: no off_cmd_topic for ' + name); return null; }
return { topic: fcfg.off_cmd_topic, payload: fcfg.off_cmd_payload, _device: name };

const parts = (msg.topic || '').split('/');
const name = parts[2];
const v = String(msg.payload || '').toUpperCase();
if (!name) return null;
if (v !== 'ON' && v !== 'OFF' && v !== 'AUTO') { node.warn('override: bad value ' + v); return null; }
const freezers = global.get('freezers') || {};
const dev = freezers[name];
if (!dev) { node.warn('override: unknown freezer ' + name); return null; }
dev.override = v;
freezers[name] = dev;
global.set('freezers', freezers);
return { device_name: name, trigger: 'override' };

// For each freezer, emit one query against infra.temperature (field value,
// tag Device) and one against tmp.power (field val, tag device). The two
// result sets are merged by time in fc_model_join. Output 0 -> temperature
// (infra), output 1 -> power (tmp).
const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
const temps = [];
const pwrs  = [];
for (const name of Object.keys(fs)) {
  const f = fs[name];
  if (!f.temp_device || !f.power_device) continue;
  temps.push({
    device_name: name,
    kind: 'temp',
    query: "SELECT mean(value) AS temp FROM temperature WHERE \"Device\" = '" + f.temp_device + "' AND time > now() - 7d GROUP BY time(5m) fill(previous)"
  });
  pwrs.push({
    device_name: name,
    kind: 'pwr',
    query: "SELECT mean(val) AS pwr FROM power WHERE device = '" + f.power_device + "' AND time > now() - 7d GROUP BY time(5m) fill(previous)"
  });
}
return [temps, pwrs];

// Buffers the temperature and power result sets per device and emits a
// single merged series once both sides have arrived. Rows are keyed by the
// 5-min bucket timestamp. Downstream fc_model_fn expects
// [{time, temp, pwr}, ...] sorted ascending in msg.payload.
const name = msg.device_name;
const kind = msg.kind;
if (!name || !kind) return null;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const buf = context.get('buf') || {};
buf[name] = buf[name] || {};
buf[name][kind] = rows;
if (!buf[name].temp || !buf[name].pwr) {
  context.set('buf', buf);
  return null;
}
const byTime = new Map();
for (const r of buf[name].temp) {
  if (!r || !r.time) continue;
  const ts = new Date(r.time).getTime();
  if (isNaN(ts)) continue;
  byTime.set(ts, { time: r.time, temp: r.temp == null ? null : Number(r.temp), pwr: null });
}
for (const r of buf[name].pwr) {
  if (!r || !r.time) continue;
  const ts = new Date(r.time).getTime();
  if (isNaN(ts)) continue;
  const cur = byTime.get(ts) || { time: r.time, temp: null, pwr: null };
  cur.pwr = r.pwr == null ? null : Number(r.pwr);
  byTime.set(ts, cur);
}
delete buf[name];
context.set('buf', buf);
const merged = Array.from(byTime.keys()).sort((a, b) => a - b).map(t => byTime.get(t));
return { device_name: name, payload: merged };

// Produces per-device cooling_rate, warming_rate and running_power from the
// last 7 days of 5-min buckets produced by fc_model_join. A bucket is
// classified as 'on' when mean power > 30W, 'off' when < 5W; anything
// between is ignored as transitional. dT/dt between consecutive buckets of
// the same class is one sample. Rows with a missing side (null temp or
// null pwr) are dropped.
const name = msg.device_name;
if (!name) return null;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length < 2) return null;
const ONW = 30, OFFW = 5;
const coolingSamples = [], warmingSamples = [], runningPowers = [];
for (let i = 1; i < rows.length; i++) {
  const a = rows[i - 1], b = rows[i];
  if (!a || !b) continue;
  const ta = a.time ? new Date(a.time).getTime() : null;
  const tb = b.time ? new Date(b.time).getTime() : null;
  if (!ta || !tb || tb <= ta) continue;
  const Ta = Number(a.temp), Tb = Number(b.temp);
  const Pa = Number(a.pwr),  Pb = Number(b.pwr);
  if (isNaN(Ta) || isNaN(Tb) || isNaN(Pa) || isNaN(Pb)) continue;
  const dtMin = (tb - ta) / 60000;
  if (dtMin < 1 || dtMin > 60) continue;
  const dT = (Tb - Ta) / dtMin;
  const avgP = (Pa + Pb) / 2;
  if (Pa > ONW && Pb > ONW) {
    coolingSamples.push(dT);
    runningPowers.push(avgP);
  } else if (Pa < OFFW && Pb < OFFW) {
    warmingSamples.push(dT);
  }
}
function mean(a) { return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null; }
const cooling = mean(coolingSamples);
const warming = mean(warmingSamples);
const runPwr = mean(runningPowers);
const freezers = global.get('freezers') || {};
const dev = freezers[name];
if (!dev) return null;
const model = dev.model || {};
if (cooling != null && cooling < -0.01) model.cooling_rate_c_per_min = Math.round(cooling * 1000) / 1000;
if (warming != null && warming > 0.002) model.warming_rate_c_per_min = Math.round(warming * 1000) / 1000;
if (runPwr != null && runPwr > 20)     model.running_power_w = Math.round(runPwr);
model.samples = coolingSamples.length + warmingSamples.length;
model.last_refresh = Date.now();
dev.model = model;
freezers[name] = dev;
global.set('freezers', freezers);
return { topic: 'freezer_model/' + name, payload: { device: name, model: model, cooling_samples: coolingSamples.length, warming_samples: warmingSamples.length } };

